"""OSA Obsidian presentation shell for verified APR Mission Control."""
from __future__ import annotations
from .mission_control_ui_v3 import render_mission_control_v3 as _base

_CSS=r'''
:root{--o0:#05070a;--o1:#080c12;--o2:#101720;--ln:#20303e;--tx:#edf3f7;--mut:#718391;--b:#3ea6ff;--c:#51d9e8;--p:#8a7cff;--g:#55d58a;--r:#ff6474}html,body{overflow-x:hidden;background:var(--o0)!important;color:var(--tx)!important}body{background-image:linear-gradient(#ffffff08 1px,transparent 1px),linear-gradient(90deg,#ffffff08 1px,transparent 1px)!important;background-size:32px 32px!important}.osa-entry{position:fixed;z-index:120;inset:0;display:grid;grid-template-columns:58% 42%;background:var(--o0)}.oe-world{position:relative;overflow:hidden;border-right:1px solid var(--ln);padding:28px}.oe-head{display:flex;justify-content:space-between;position:relative;z-index:3}.oe-brand{font:800 13px var(--mono);letter-spacing:.08em}.oe-status{color:var(--g);font:700 9px/1.5 var(--mono);text-align:right}.oe-copy{position:absolute;z-index:3;left:32px;bottom:32px}.oe-copy h1{margin:10px 0;font:850 clamp(40px,5vw,74px)/.96 var(--sans);letter-spacing:-.05em}.oe-copy p{max-width:580px;color:var(--mut);font-size:12px;line-height:1.6}.oe-graph{position:absolute;inset:70px 10px 150px}.oe-graph svg,.osa-world svg{width:100%;height:100%}.e{stroke:#28485d;stroke-width:1.2}.e.live{stroke:#3e8fac;stroke-dasharray:5 10;animation:flow 4s linear infinite}.n circle{fill:#09121a;stroke:#3b6079;stroke-width:1.2}.n.ai circle{stroke:var(--p)}.n.proof circle{stroke:var(--g)}.n text{fill:#9db0be;font:700 9px var(--mono)}@keyframes flow{to{stroke-dashoffset:-60}}.oe-panel{display:flex;align-items:center;justify-content:center;padding:30px;background:linear-gradient(#0c1118,#070a0e)}.oe-login{width:min(460px,100%)}.oe-login h2{margin:22px 0 5px;font-size:29px}.oe-login p{color:var(--mut);line-height:1.55;font-size:12px}.oe-login label{display:block;margin:12px 0 6px;color:#708391;font:700 8px var(--mono);letter-spacing:.1em}.oe-login input,.oe-login select{box-sizing:border-box;width:100%;height:44px;border:1px solid var(--ln);border-radius:7px;background:#090e14;color:#dce6ed;padding:0 11px}.providers{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin:12px 0}.providers button{height:41px;border:1px solid var(--ln);border-radius:7px;background:#0a1017;color:#728592;text-align:left;padding:0 10px}.providers small{float:right;color:#4f6170;font:700 7px var(--mono)}#osa-enter{width:100%;height:46px;margin-top:12px;border:1px solid #3a8fd1;border-radius:7px;background:#0e3048;color:#e8f7ff;font-weight:850}.sec{margin-top:13px;padding:10px;border-left:2px solid var(--b);background:#08121b;color:#8193a1;font-size:10px;line-height:1.6}.osa-shell{display:none}.osa-entered .osa-shell{display:block}.osa-entered .review-strip{display:none!important}.osa-side{position:fixed;z-index:80;left:0;top:0;bottom:0;width:224px;box-sizing:border-box;border-right:1px solid var(--ln);background:#060a0fef;padding:12px 9px;overflow:auto}.os-brand{padding:7px 8px 14px;font:850 12px var(--mono);letter-spacing:.06em}.os-brand small{display:block;margin-top:4px;color:#546675;font-size:7px}.os-nav b{display:block;padding:13px 8px 5px;color:#4f6070;font:700 7px var(--mono);letter-spacing:.14em}.os-nav a,.os-nav button{box-sizing:border-box;width:100%;min-height:34px;display:flex;align-items:center;gap:8px;border:0;border-radius:6px;background:transparent;color:#8fa0ad;text-decoration:none;padding:0 8px;font-size:10px;text-align:left}.os-nav a:hover,.os-nav button:hover{background:#0e1620;color:#fff}.os-nav .on{background:#101923;color:#fff;box-shadow:inset 2px 0 var(--b)}.os-top{position:fixed;z-index:75;left:224px;right:0;top:0;height:58px;box-sizing:border-box;display:flex;align-items:center;padding:9px 14px;border-bottom:1px solid var(--ln);background:#070b10e8;backdrop-filter:blur(16px)}#osa-command{flex:1;max-width:720px;height:38px;border:1px solid #263848;border-radius:7px;background:#0a1017;color:#667887;text-align:left;padding:0 12px}.os-live{margin-left:auto;color:var(--g);font:700 8px var(--mono)}body.osa-entered>.wrap{margin-left:224px!important;padding-top:58px!important;max-width:none!important;width:auto!important}.osa-world{position:relative;min-height:410px;margin:0 0 18px;border:1px solid var(--ln);border-radius:9px;overflow:hidden;background:#070c12e8}.ow-head{position:relative;z-index:2;display:flex;justify-content:space-between;padding:12px 14px;border-bottom:1px solid var(--ln);font:800 10px var(--mono)}.ow-head span{color:#657786;font-size:7px}.osa-world svg{position:absolute;left:0;right:0;top:42px;height:calc(100% - 42px)}.proof-rule{margin:10px 0 20px;padding:10px 12px;border:1px solid #55d58a35;border-left:2px solid var(--g);border-radius:7px;background:#55d58a0a;color:#718391;font-size:10px}.proof-rule b{color:var(--g);font:800 9px var(--mono)}.osa-entered .card,.osa-entered .proof-console,.osa-entered .evidence,.osa-entered .studio,.osa-entered .stats{border-radius:8px!important;background-color:#080d13dc!important}.osa-palette{position:fixed;z-index:140;inset:0;display:none;justify-content:center;padding-top:10vh;background:#0009;backdrop-filter:blur(5px)}.osa-palette.open{display:flex}.op-box{width:min(640px,calc(100% - 24px));height:max-content;border:1px solid #263848;border-radius:10px;background:#080d13;overflow:hidden}.op-box input{box-sizing:border-box;width:100%;height:52px;border:0;border-bottom:1px solid var(--ln);background:#0b1118;color:#fff;padding:0 14px;outline:0}.op-box a{display:flex;justify-content:space-between;min-height:40px;align-items:center;padding:0 12px;color:#a9b7c1;text-decoration:none}.op-box a:hover{background:#101923}.op-box small{color:#566a79;font:700 7px var(--mono)}@media(max-width:1024px){body.osa-entered>.wrap{margin-left:64px!important}.osa-side{width:64px}.os-brand small,.os-nav b,.os-nav span{display:none}.os-nav a,.os-nav button{justify-content:center}.os-top{left:64px}.osa-entry{grid-template-columns:1fr}.oe-world{min-height:40dvh;border-right:0;border-bottom:1px solid var(--ln)}.oe-panel{min-height:60dvh}.oe-graph{inset:50px 10px 85px}.oe-copy{bottom:18px}.oe-copy p{display:none}}@media(max-width:640px){body.osa-entered>.wrap{margin:0!important;padding:56px 8px 67px!important}.osa-side{top:auto;right:0;bottom:0;width:auto;height:61px;border-right:0;border-top:1px solid var(--ln);display:flex;justify-content:center;padding:5px;overflow-x:auto}.os-brand,.os-nav b{display:none}.os-nav{display:flex}.os-nav a,.os-nav button{min-width:50px;height:48px}.os-nav a:nth-of-type(n+6),.os-nav button:nth-of-type(n+6){display:none}.os-top{left:0;height:56px;padding:8px}.os-live{display:none}.oe-world{min-height:38dvh;padding:16px}.oe-panel{min-height:62dvh;padding:16px}.oe-copy{left:16px}.oe-copy h1{font-size:34px}.providers{grid-template-columns:1fr}.osa-world{min-height:350px}.ow-head span{display:none}}@media(prefers-reduced-motion:reduce){.e.live{animation:none!important}}
'''

_ENTRY=r'''<section class="osa-entry" id="osa-entry"><div class="oe-world"><div class="oe-head"><div class="oe-brand">OSA FRAMEWORK<br><small>AGENTIC SYSTEMS OPERATING SYSTEM</small></div><div class="oe-status">CONTROL PLANE<br>SYSTEM ONLINE</div></div><div class="oe-graph"><svg viewBox="0 0 760 470"><g><line class="e live" x1="380" y1="220" x2="235" y2="130"/><line class="e" x1="380" y1="220" x2="520" y2="125"/><line class="e live" x1="380" y1="220" x2="565" y2="280"/><line class="e" x1="380" y1="220" x2="210" y2="305"/><line class="e live" x1="210" y1="305" x2="345" y2="405"/><line class="e" x1="345" y1="405" x2="520" y2="410"/></g><g class="n" transform="translate(380 220)"><circle r="12"/><text x="18" y="4">MISSION</text></g><g class="n" transform="translate(235 130)"><circle r="10"/><text x="16" y="4">AGENT</text></g><g class="n ai" transform="translate(520 125)"><circle r="10"/><text x="16" y="4">MODEL</text></g><g class="n" transform="translate(565 280)"><circle r="10"/><text x="16" y="4">TOOL</text></g><g class="n" transform="translate(210 305)"><circle r="10"/><text x="16" y="4">EVIDENCE</text></g><g class="n proof" transform="translate(345 405)"><circle r="10"/><text x="16" y="4">PROOF</text></g><g class="n" transform="translate(520 410)"><circle r="9"/><text x="15" y="4">REPLAY</text></g></svg></div><div class="oe-copy"><div class="eyebrow">OBSIDIAN KNOWLEDGE + RUNTIME + PROOF CONTROL PLANE</div><h1>ONE SYSTEM.<br>EVERY AGENT.<br>EVERY PROOF.<br>EVERY STATE.</h1><p>Mission, runtime, evidence, proof and replay are one operational world.</p></div></div><div class="oe-panel"><div class="oe-login"><div class="oe-brand">OSA FRAMEWORK</div><h2>Welcome to OSA</h2><p>Enter the proof-first control plane. Local-operator access is real; OAuth and SSO are not faked.</p><label>WORKSPACE / ORGANIZATION</label><select><option>Local APR Workspace</option></select><div class="providers"><button disabled>GitHub <small>NOT CONNECTED</small></button><button disabled>Google <small>NOT CONNECTED</small></button><button disabled>Microsoft <small>NOT CONNECTED</small></button><button disabled>Enterprise SSO <small>NOT CONNECTED</small></button></div><label>DEPLOYMENT MODE</label><input value="Self-hosted / Local Operator" disabled><button id="osa-enter">ENTER CONTROL PLANE</button><div class="sec"><b>Proof-first runtime.</b> Existing APR host restrictions, request token protection and proof verification remain the security boundary.</div></div></div></section>'''

_SHELL=r'''<div class="osa-shell"><aside class="osa-side"><div class="os-brand">OSA FRAMEWORK<small>CONTROL PLANE</small></div><nav class="os-nav"><b>HOME</b><a class="on" href="#osa-world"><span>WORLD</span></a><b>BUILD</b><a href="#mission-studio"><span>STUDIO</span></a><a href="#missions-section"><span>MISSIONS</span></a><b>OBSERVE</b><a href="#runs-section"><span>TRACING</span></a><b>PROOF</b><a href="#runs-section"><span>PROOFS</span></a><button data-replay><span>REPLAY</span></button><b>CONTROL</b><a href="#system-status"><span>SYSTEM</span></a></nav></aside><header class="os-top"><button id="osa-command">Search agents, missions, proofs, traces, repos or commands... &nbsp; Ctrl K</button><div class="os-live">SYSTEM ONLINE</div></header></div>'''

_WORLD=r'''<section class="osa-world" id="osa-world"><div class="ow-head">OSA KNOWLEDGE WORLD <span>SCHEMA + LIVE APR STATE</span></div><svg viewBox="0 0 900 350"><g><line class="e live" x1="450" y1="135" x2="285" y2="75"/><line class="e" x1="450" y1="135" x2="610" y2="75"/><line class="e live" x1="450" y1="135" x2="690" y2="180"/><line class="e" x1="450" y1="135" x2="255" y2="215"/><line class="e live" x1="255" y1="215" x2="470" y2="295"/><line class="e" x1="470" y1="295" x2="650" y2="295"/></g><g class="n" transform="translate(450 135)"><circle r="11"/><text x="17" y="3">MISSION</text></g><g class="n" transform="translate(285 75)"><circle r="10"/><text x="16" y="3">AGENT</text></g><g class="n ai" transform="translate(610 75)"><circle r="10"/><text x="16" y="3">MODEL</text></g><g class="n" transform="translate(690 180)"><circle r="10"/><text x="16" y="3">TOOL</text></g><g class="n" transform="translate(255 215)"><circle r="10"/><text x="16" y="3">EVIDENCE</text></g><g class="n proof" transform="translate(470 295)"><circle r="10"/><text x="16" y="3">PROOF</text></g><g class="n" transform="translate(650 295)"><circle r="9"/><text x="15" y="3">REPLAY</text></g></svg></section><div class="proof-rule"><b>CLAIM != PROOF</b> Evidence, verification status, Proof Bundle and history remain explicit.</div>'''

_PAL=r'''<div class="osa-palette" id="osa-palette"><div class="op-box"><input id="op-input" placeholder="Type a command..."><a href="#mission-studio">Run Mission <small>MISSION</small></a><a href="#runs-section">Verify Proof <small>PROOF</small></a><a href="#runs-section">Inspect Trace <small>TRACE</small></a><a href="#osa-world">Open Knowledge World <small>WORLD</small></a></div></div>'''

_JS=r'''<script>(()=>{const e=document.querySelector('#osa-entry'),p=document.querySelector('#osa-palette');const enter=()=>{document.body.classList.add('osa-entered');e.style.display='none';sessionStorage.setItem('osa-entered','1')},open=()=>{p.classList.add('open');document.querySelector('#op-input').focus()},close=()=>p.classList.remove('open');document.querySelector('#osa-enter').onclick=enter;document.querySelector('#osa-command').onclick=open;p.onclick=x=>x.target===p&&close();document.onkeydown=x=>{if((x.ctrlKey||x.metaKey)&&x.key.toLowerCase()==='k'){x.preventDefault();open()}if(x.key==='Escape')close()};document.querySelectorAll('[data-replay]').forEach(x=>x.onclick=()=>document.querySelector('#runs-section')?.scrollIntoView({behavior:'smooth'}));if(sessionStorage.getItem('osa-entered'))enter()})();</script>'''

def render_mission_control_obsidian(csrf_token:str)->str:
    """Wrap the existing APR UI without changing execution or proof contracts."""
    h=_base(csrf_token); sm="  </style>"; bm="<body>"; mm="    <main>"; em="</body>"
    if sm not in h or bm not in h or mm not in h: raise RuntimeError("APR Mission Control renderer markers changed")
    h=h.replace(sm,_CSS+sm,1).replace(bm,bm+_ENTRY+_SHELL,1).replace(mm,mm+_WORLD,1).replace(em,_PAL+_JS+em,1)
    return h
